                            FileDescriptor[] descriptors, FileDescriptor pipeFd, PrintStream newStderr)
                            throws ZygoteInit.MethodAndArgsCaller {
    ...
    ZygoteInit.invokeStaticMain(cloader, className, mainArgs);
