        List<Cookie> cookies = client.cookieJar().loadForRequest(request.url());
        if (!cookies.isEmpty()) {
          result.header("Cookie", cookieHeader(cookies));
        }

        if (request.header("User-Agent") == null) {
          result.header("User-Agent", Version.userAgent());
        }

        return result.build();
      }
