```kotlin
class DataSource {
    private val liveData = MutableLiveData<Int>()

    fun observe(owner: LifecycleOwner, observer: Observer<Int>) {
        liveData.observe(owner, observer)
    }

    fun loadData() {
        Thread(Runnable {
            // 加载数据
            //liveData.value = 123 // 主线程中
            liveData.postValue(123) // 子线程中
        }).start()
    }
}

// Activity中监听
